/* Local-only PDF export. No progress or notes leave the browser. */
const TAKEAWAY = {
 title:T('Für deinen nächsten Service','For your next service','Pour votre prochain service'),
 intro:T('Die wichtigsten Gedanken aus deiner Experience. Zum Nachlesen, Besprechen und Ausprobieren im Restaurant.','Key reminders from your experience, to revisit, discuss and put into practice at work.','Les points essentiels du parcours, à relire, à échanger avec votre équipe et à mettre en pratique au restaurant.'),
 download:T('Zusammenfassung herunterladen','Download your summary','Télécharger le récapitulatif'),
 notes:T('Meine gespeicherten Notizen hinzufügen','Include my saved notes','Ajouter mes notes enregistrées'),
 sections:[
 [T('Vor dem Service','Before service','Avant le service'),T('Kläre im Briefing, was heute anders ist: Gerichte, Zutaten, ausverkaufte Produkte, Reservierungen und besondere Wünsche. Prüfe deine Station und frage nach, wer bei Unklarheiten hilft.','Use the briefing to check menu changes, ingredients, unavailable items, reservations and special requests. Check your station and know who to ask when you are unsure.','Au briefing, faites le point sur les changements du jour : plats, ingrédients, ruptures, réservations et demandes particulières. Vérifiez votre poste et sachez à qui vous adresser en cas de doute.')],
 [T('Aufmerksam empfangen','A thoughtful welcome','Un accueil attentif'),T('Nimm ankommende Gäste wahr, auch wenn du gerade beschäftigt bist. Kläre die Reservierung und begleite sie nach den Abläufen eures Hauses. Höre zu, bevor du eine Empfehlung gibst.','Acknowledge arriving guests even when you are busy. Check their reservation and follow your restaurant’s approach to seating. Listen before making a recommendation.','Accueillez les clients qui arrivent, même si vous êtes occupé. Vérifiez leur réservation et installez-les selon les habitudes de la maison. Écoutez leurs envies avant de conseiller.')],
 [T('Ein Gericht verständlich beschreiben','Describe a dish clearly','Présenter un plat simplement'),T('Nenne das Hauptprodukt, die Zubereitung und ein oder zwei Merkmale: etwa geröstet, frisch oder cremig. Verwende Begriffe, die du erklären kannst. Herkunft und Zutaten nur nennen, wenn du sie sicher kennst.','Describe the main ingredient, cooking method and one or two qualities, such as roasted, fresh or creamy. Use words you can explain. Only give details about ingredients or origin that you have verified.','Présentez le produit principal, sa cuisson et une ou deux caractéristiques : des notes grillées, de la fraîcheur, une texture crémeuse. Employez des mots simples. Ne précisez l’origine ou les ingrédients que si vous les connaissez avec certitude.')],
 [T('Bei Allergien nichts vermuten','Never guess about allergies','Ne rien supposer en cas d’allergie'),T('Nimm die Angabe ernst und kläre Zutaten sowie mögliche Kreuzkontakte nach eurem festgelegten Ablauf mit der Küche. Gib die Information eindeutig weiter. Versprich keine Eignung, die nicht bestätigt wurde.','Take the guest’s information seriously. Follow your restaurant’s procedure to check ingredients and possible cross-contact with the kitchen. Pass the information on clearly. Never promise suitability without confirmation.','Prenez la demande au sérieux. Vérifiez avec la cuisine les ingrédients et les risques de contact croisé, selon la procédure de l’établissement. Transmettez clairement l’information. Ne garantissez jamais qu’un plat convient sans confirmation.')],
 [T('Eine Begleitung empfehlen','Recommend a pairing','Conseiller un accord'),T('Frage nach Vorlieben und Preisrahmen. Berücksichtige neben dem Hauptprodukt auch Sauce, Zubereitung und Intensität. Ähnliche Aromen oder ein bewusster Kontrast können ein guter Ausgangspunkt sein. Ein Pairing ist ein Vorschlag, keine feste Regel.','Ask about preferences and budget. Consider the sauce, preparation and intensity as well as the main ingredient. Similar aromas or a deliberate contrast can be useful starting points. A pairing is a suggestion, not a fixed rule.','Demandez les goûts du client et son budget. Tenez compte de la sauce, de la préparation et de l’intensité du plat, pas seulement du produit principal. Des arômes proches ou un contraste peuvent guider votre choix. Un accord reste une proposition, pas une règle absolue.')],
 [T('Auch ohne Alkohol beraten','Offer alcohol-free choices','Conseiller aussi sans alcool'),T('Beschreibe alkoholfreie Getränke genauso sorgfältig: Süße, Säure, Bitterkeit, Aromen und Textur. Prüfe Zusammensetzung und Alkoholgehalt, wenn vollständiger Alkoholverzicht wichtig ist. Nicht jedes fermentierte Getränk ist alkoholfrei.','Describe alcohol-free drinks with the same care: sweetness, acidity, bitterness, aromas and texture. Check ingredients and alcohol content when complete avoidance matters. Not every fermented drink is alcohol-free.','Décrivez les boissons sans alcool avec autant de soin : douceur, acidité, amertume, arômes et texture. Vérifiez leur composition et leur teneur en alcool si le client doit l’éviter totalement. Une boisson fermentée n’est pas forcément sans alcool.')],
 [T('Am Tisch sicher handeln','Work confidently at the table','Les bons gestes à table'),T('Bestätige bei Wein die bestellte Flasche und den Jahrgang, bevor du öffnest. Übe Öffnen und Einschenken mit dem Verantwortlichen im Haus. Achte während des Services auf Tempo, Gespräch und Signale der Gäste.','Confirm the ordered wine and vintage before opening. Practise opening and pouring with your supervisor. During service, pay attention to pacing, conversation and your guests’ signals.','Présentez la bouteille et confirmez le vin et le millésime commandés avant de l’ouvrir. Entraînez-vous à ouvrir et à servir avec votre responsable. Pendant le repas, soyez attentif au rythme et aux signes des convives.')],
 [T('Wenn etwas nicht passt','When something goes wrong','Si quelque chose ne va pas'),T('Höre zu, kläre das Anliegen und informiere den zuständigen Kollegen. Vereinbare den nächsten Schritt und frage später nach. Für deinen nächsten Dienst: Wähle eine Situation aus diesen Seiten und besprich, wie ihr sie im Haus löst.','Listen, clarify the issue and inform the colleague responsible. Agree on the next step and follow up. For your next shift, choose one situation from these pages and discuss how your restaurant handles it.','Écoutez, précisez le problème et prévenez le collègue concerné. Convenez de la suite et revenez vers le client. Pour votre prochain service, choisissez une situation dans ces pages et voyez avec votre équipe comment vous la gérez dans votre établissement.')]
 ]
};
function takeawayPanel(){return `<section class="takeaway-panel" aria-labelledby="takeaway-title"><h2 id="takeaway-title">${txt(T('Gut gemacht. Und jetzt: mitnehmen.','Well done. Take it with you.','Bravo ! Gardez l’essentiel.'))}</h2><p>${txt(T('Du hast alle Einheiten abgeschlossen. Nimm die wichtigsten Hinweise als PDF mit in deinen nächsten Dienst.','You have completed every lesson. Take the key reminders into your next service with this PDF.','Vous avez terminé toutes les séquences. Retrouvez les points essentiels dans un PDF à garder pour vos prochains services.'))}</p><label class="takeaway-check"><input type="checkbox" id="takeaway-notes" ${notes.length?'':'disabled'}> ${txt(TAKEAWAY.notes)}${notes.length?'':` · ${txt(T('Noch keine gespeichert','None saved yet','Aucune note enregistrée'))}`}</label><div class="actions"><button class="primary" id="takeaway-download">${txt(TAKEAWAY.download)}${arrow}</button><a href="#lab">${txt(T('Im Geschmackslabor weiter ausprobieren','Keep exploring in the flavour lab','Continuer au laboratoire du goût'))}</a></div><p class="local-status" id="takeaway-status" role="status"></p></section>`;}
const journeyBeforeTakeaway=journey;
journey=function(){const html=journeyBeforeTakeaway();return LESSONS.every(l=>completed.includes(l.id))?html.replace('<div class="flow-progress">',takeawayPanel()+'<div class="flow-progress">'):html;};
const lessonBeforeTakeaway=lessonPage;
lessonPage=function(id){const html=lessonBeforeTakeaway(id);return LESSONS.every(l=>completed.includes(l.id))&&html.includes('lesson-success')?html+takeawayPanel():html;};
let pdfRuntime;
function loadPdfRuntime(){return pdfRuntime||(pdfRuntime=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='vendor/jspdf.umd.min.js';s.onload=resolve;s.onerror=()=>{pdfRuntime=null;s.remove();reject(Error('PDF library unavailable'));};document.head.appendChild(s);}));}
async function createTakeaway(includeNotes=false){
 const exportLang=lang, t=x=>x[exportLang], savedNotes=includeNotes?notes.map(n=>({...n})):[];
 await loadPdfRuntime();
 const fontPaths=['assets/della-respira.ttf','assets/josefin-sans.ttf'];
 const fonts=await Promise.all(fontPaths.map(async path=>{const r=await fetch(path);if(!r.ok)throw Error('Font unavailable');const bytes=new Uint8Array(await r.arrayBuffer());let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(str);}));
 const pdf=new window.jspdf.jsPDF({unit:'mm',format:'a4',compress:true});
 fonts.forEach((f,i)=>{pdf.addFileToVFS(`font${i}.ttf`,f);pdf.addFont(`font${i}.ttf`,i?'Body':'Title','normal');});
 pdf.setProperties({title:t(TAKEAWAY.title),author:'SALONFORMAT',subject:'Service'});
 let y=0;
 function page(title,sub){pdf.setFillColor('#f5f1e7');pdf.rect(0,0,210,297,'F');pdf.setTextColor('#172c49');pdf.setFont('Body');pdf.setFontSize(12);pdf.text('salonformat.',22,20);pdf.setFont('Title');pdf.setFontSize(27);pdf.setTextColor('#246778');pdf.text(title,22,39);pdf.setTextColor('#172c49');pdf.setFillColor('#e7dc83');pdf.roundedRect(22,45,30,2,1,1,'F');y=57;if(sub)paragraph(sub,11.5);}
 function paragraph(text,size=12){pdf.setFont('Body');pdf.setFontSize(size);const lines=pdf.splitTextToSize(text,166);for(const line of lines){if(y>267){pdf.addPage();page(t(T('Notizen','Notes','Notes personnelles')),'');pdf.setFont('Body');pdf.setFontSize(size);}pdf.text(line,22,y);y+=5.6;}y+=5;}
 function heading(text){pdf.setFont('Title');pdf.setFontSize(15);pdf.text(text,22,y);y+=8;}
 page(t(TAKEAWAY.title),t(TAKEAWAY.intro));
 TAKEAWAY.sections.forEach(([h,p],i)=>{if(i===4){pdf.addPage();page(t(T('Am Tisch','At the table','À table')),'');}heading(t(h));paragraph(t(p));y+=4;});
 if(savedNotes.length){pdf.addPage();page(t(T('Meine Notizen','My notes','Mes notes')),t(T('Persönliche Einträge aus deinem Notizbuch.','Personal entries from your notebook.','Vos notes personnelles prises pendant le parcours.')));for(const n of savedNotes){if(y>240){pdf.addPage();page(t(T('Meine Notizen','My notes','Mes notes')),'');}const lesson=LESSONS.find(l=>l.id===n.lesson);if(lesson){const h=pdf.splitTextToSize(t(lesson.title),166);paragraph(h.join(' '),13);}paragraph(n.text);}}
 const count=pdf.getNumberOfPages();for(let i=1;i<=count;i++){pdf.setPage(i);pdf.setDrawColor('#172c49');pdf.setLineWidth(.2);pdf.line(22,278,188,278);pdf.setFont('Body');pdf.setFontSize(9);pdf.text(t(T('Lernbegleiter · Die Abläufe eures Hauses gelten.','Learning companion · Follow your restaurant’s procedures.','Aide-mémoire · Suivez les procédures de votre établissement.')),22,285);pdf.text(`${i} / ${count}`,188,291,{align:'right'});pdf.textWithLink('salonformat.com',22,291,{url:'https://salonformat.com/'});}
 pdf.save(`SALONFORMAT-${exportLang}.pdf`);
}
const bindBeforeTakeaway=bind;
bind=function(){bindBeforeTakeaway();$('#takeaway-download')?.addEventListener('click',async()=>{const button=$('#takeaway-download'),status=$('#takeaway-status');button.disabled=true;status.textContent=txt(T('Dein PDF wird erstellt …','Preparing your PDF…','Préparation de votre PDF…'));try{await createTakeaway($('#takeaway-notes').checked);status.textContent=txt(T('Dein PDF ist bereit.','Your PDF is ready.','Votre PDF est prêt.'));}catch(e){console.error(e);status.textContent=txt(T('Der Download hat nicht geklappt. Bitte versuche es noch einmal.','The download failed. Please try again.','Le téléchargement a échoué. Veuillez réessayer.'));}finally{button.disabled=false;}});};
render(false);
